import {evaluateCover,coverEmail} from './cover-model.mjs';
export function createCoverUI({e,actor,toast,dirty}){
 let token=0,data=null,assignments={},showEmail=false,savedCurrent=false,busy=false;
 const today=()=>new Date(Date.now()+5*3600000).toISOString().slice(0,10);
 async function api(path,body){const r=await fetch('/api/admin/'+path,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error||'Cover could not be saved.');return d;}
 function page(p){const n=++token;if(actor()?.role!=='report-reviewer')return'<p class="error">Administrator access required.</p>';queueMicrotask(async()=>{try{const r=await api('cover?'+new URLSearchParams({date:p.get('date')||today()}));if(n!==token||!document.querySelector('#cover-content'))return;data=r;assignments={...r.assignments};savedCurrent=!r.stale;showEmail=evaluateCover(r,assignments).complete;paint();}catch(err){if(n===token&&document.querySelector('#cover-content'))document.querySelector('#cover-content').innerHTML='<p class="error">'+e(err.message)+'</p>';}});return'<section class="vle"><div class="learning-section-title"><h1>Cover</h1><span>Daily staff absence & lesson cover</span></div><div id="cover-content" aria-live="polite">Opening the cover sheet…</div></section>';}
 function paint(){const root=document.querySelector('#cover-content');if(!root||!data)return;const result=evaluateCover(data,assignments),absent=data.absentIds.map(id=>data.staff.find(t=>t.id===id)),noLessons=absent.filter(t=>!data.lessons.some(r=>r.absentId===t.id)),copyReady=result.complete&&savedCurrent&&data.savedComplete;root.innerHTML='<form data-cover-date class="community-filters"><label>Date<input type="date" name="date" aria-label="Cover date" required value="'+e(data.date)+'"></label><button class="btn">Load day</button><span>'+e(data.timetable)+' · '+data.lessons.length+' '+(data.lessons.length===1?'lesson':'lessons')+' · '+result.assigned+' assigned</span></form><section class="vle-panel cover-absences"><form data-cover-add><label class="vle-field">Who is absent?<select name="teacher" aria-label="Select absent teacher"><option value="">Choose a staff member…</option>'+data.staff.filter(t=>!data.absentIds.includes(t.id)).map(t=>'<option value="'+e(t.id)+'">'+e(t.name)+' · '+e(t.area)+'</option>').join('')+'</select></label><button class="btn" '+(busy?'disabled':'')+'>Add absent teacher</button></form><div class="cover-absent-tags">'+absent.map(t=>'<span>'+e(t.name)+' <button type="button" class="text-button" data-cover-remove="'+e(t.id)+'" aria-label="Remove '+e(t.name)+' from absent staff">×</button></span>').join('')+'</div>'+(!absent.length?'<p>Select one or more absent staff to show their lessons for this date.</p>':'')+(noLessons.length?'<p class="vle-note">No timetabled lessons for '+noLessons.map(t=>e(t.name)).join(', ')+' on this date.</p>':'')+(!data.lessons.length&&(!savedCurrent||data.revision)?'<button type="button" class="btn" data-cover-save="draft">Save absence list</button>':'')+'</section>'+(data.stale?'<p class="error">Staff availability or the timetable changed since this plan was saved. Check the choices and save a revised plan.</p>':'')+(result.conflicts?'<p class="error">'+result.conflicts+' cover choices are no longer available. Choose another teacher.</p>':'')+(data.lessons.length?(showEmail&&result.complete?'<section class="vle-panel"><div class="learning-section-title"><h2>Email table</h2><button type="button" class="btn" data-cover-edit>Edit cover choices</button></div><p>'+(copyReady?'Saved cover plan · '+e(new Date(data.savedAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'})):'All lessons have cover. Save the plan to enable copying.')+'</p><div class="table-wrap cover-email-table">'+coverEmail(data,result.rows).html+'</div><div class="vle-actions"><button type="button" class="btn primary" data-cover-save="complete" '+(busy?'disabled':'')+'>Save cover plan</button><button type="button" class="btn" data-cover-copy '+(!copyReady||busy?'disabled':'')+'>Copy table for email</button></div><p role="status" data-cover-copy-status></p><div data-cover-copy-fallback></div></section>':'<section class="vle-panel"><h2>Assign cover</h2><p>Choices exclude absent staff, their own lessons, blocked timetable slots and other cover at overlapping times.</p><div class="table-wrap cover-assignment-table"><table class="data-table"><thead><tr><th>Absent teacher</th><th>Period / time</th><th>Class / room</th><th>Cover teacher</th></tr></thead><tbody>'+result.rows.map(r=>'<tr><td>'+e(r.absentName)+'</td><td><strong>'+e(r.period)+'</strong><br>'+e(r.from)+'–'+e(r.to)+'</td><td>'+e(r.className)+'<br><small>'+e(r.room)+'</small></td><td><select data-cover-choice="'+e(r.key)+'" aria-label="Cover for '+e(r.absentName)+' period '+e(r.period)+'"><option value="">'+(r.candidates.length?'Choose a free teacher…':'No free teacher available')+'</option>'+(!r.valid?'<option selected disabled value="'+e(r.coverId)+'">'+e(r.coverName||r.coverId)+' · unavailable</option>':'')+r.candidates.map(t=>'<option value="'+e(t.id)+'" '+(r.coverId===t.id?'selected':'')+'>'+e(t.name)+' · '+(data.schedules[t.id]||[]).length+' lessons</option>').join('')+'</select>'+(r.problem?'<small class="error">'+e(r.problem)+'</small>':'<small>'+r.candidates.length+' free '+(r.candidates.length===1?'teacher':'teachers')+'</small>')+'</td></tr>').join('')+'</tbody></table></div><div class="vle-actions"><button type="button" class="btn" data-cover-save="draft" '+(busy?'disabled':'')+'>Save draft</button><button type="button" class="btn primary" data-cover-preview '+(!result.complete?'disabled':'')+'>Show email table</button></div></section>'):(absent.length?'<p>No cover is required for these staff on this date.</p>':''))+'<p class="muted"><small>'+(savedCurrent&&data.savedAt?'Last saved '+e(new Date(data.savedAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'})):data.revision?'Unsaved changes to this day’s plan.':'No cover plan saved for this day.')+' · Saves remain in this browser. Copying does not send an email.</small></p>';bind(root);}
 async function changeAbsences(ids){if(busy)return;busy=true;try{const next=await api('cover?'+new URLSearchParams({date:data.date,absent:ids.join(',')}));if(next.revision!==data.revision)throw Error('This day’s plan changed elsewhere. Reload the day before changing it.');const keys=new Set(next.lessons.map(r=>r.key));assignments=Object.fromEntries(Object.entries(assignments).filter(([key])=>keys.has(key)));data=next;savedCurrent=false;showEmail=false;dirty(true);busy=false;paint();}catch(err){toast(err.message);}finally{busy=false;}}
 function bind(root){root.querySelector('[data-cover-date]')?.addEventListener('submit',ev=>{ev.preventDefault();location.hash='/cover?'+new URLSearchParams({date:ev.currentTarget.elements.date.value});});root.querySelector('[data-cover-add]')?.addEventListener('submit',ev=>{ev.preventDefault();const id=ev.currentTarget.elements.teacher.value;if(id)changeAbsences([...data.absentIds,id]);else toast('Choose an absent staff member.');});root.querySelectorAll('[data-cover-remove]').forEach(b=>b.addEventListener('click',()=>changeAbsences(data.absentIds.filter(id=>id!==b.dataset.coverRemove))));root.querySelectorAll('[data-cover-choice]').forEach(s=>s.addEventListener('change',()=>{assignments[s.dataset.coverChoice]=s.value;savedCurrent=false;dirty(true);showEmail=evaluateCover(data,assignments).complete;paint();}));root.querySelector('[data-cover-edit]')?.addEventListener('click',()=>{showEmail=false;paint();});root.querySelector('[data-cover-preview]')?.addEventListener('click',()=>{showEmail=true;paint();});root.querySelectorAll('[data-cover-save]').forEach(b=>b.addEventListener('click',async()=>{if(busy)return;busy=true;b.disabled=true;try{const complete=b.dataset.coverSave==='complete',r=await api('cover-save',{date:data.date,absentIds:data.absentIds,assignments,signature:data.signature,expectedRevision:data.revision,complete});Object.assign(data,{revision:r.revision,savedAt:r.savedAt,savedComplete:r.complete,stale:false});savedCurrent=true;dirty(false);toast(complete?'Cover plan saved. The email table is ready to copy.':'Cover draft saved.');}catch(err){toast(err.message);}finally{busy=false;paint();}}));root.querySelector('[data-cover-copy]')?.addEventListener('click',async()=>{try{const latest=await api('cover?'+new URLSearchParams({date:data.date}));if(latest.revision!==data.revision||latest.signature!==data.signature||latest.stale||!latest.savedComplete||!latest.summary.complete)throw Error('The saved plan or timetable changed. Reload the day before copying.');const email=coverEmail(latest,evaluateCover(latest,latest.assignments).rows);try{const selection=window.getSelection(),ranges=selection?Array.from({length:selection.rangeCount},(_,i)=>selection.getRangeAt(i).cloneRange()):[],range=document.createRange();range.selectNodeContents(root.querySelector('.cover-email-table'));selection?.removeAllRanges();selection?.addRange(range);const onCopy=event=>{if(event.clipboardData){event.clipboardData.setData('text/html',email.html);event.clipboardData.setData('text/plain',email.text);event.preventDefault();}};document.addEventListener('copy',onCopy);let copied=false;try{copied=document.execCommand('copy');}finally{document.removeEventListener('copy',onCopy);selection?.removeAllRanges();for(const old of ranges)try{selection?.addRange(old);}catch{}}if(!copied&&navigator.clipboard?.write&&typeof ClipboardItem!=='undefined')await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([email.html],{type:'text/html'}),'text/plain':new Blob([email.text],{type:'text/plain'})})]);else if(!copied)await navigator.clipboard.writeText(email.text);root.querySelector('[data-cover-copy-status]').textContent='Cover table copied. Paste it into your email.';}catch{root.querySelector('[data-cover-copy-status]').textContent='Clipboard access is unavailable. Select and copy the table above, or copy the text below.';root.querySelector('[data-cover-copy-fallback]').innerHTML='<label class="vle-field">Email text<textarea readonly rows="8">'+e(email.text)+'</textarea></label>';}}catch(err){toast(err.message);}});}
 return{page};
}
